// Generated file — do not edit by hand.
//
// Invokes every auto-generated [PdfGoogleFonts] loader (6525 static
// getters from lib/src/fonts/gfonts.dart) so the complete generated
// surface is covered by the test suite.
//
// Regenerate (from printing/, Git Bash):
//   {
//     head -22 test/font/gfonts_all_test.dart
//     sed -n 's/^  static Future<Font> \([A-Za-z0-9_]*\)().*/      await check(PdfGoogleFonts.\1());/p' lib/src/fonts/gfonts.dart
//     tail -40 test/font/gfonts_all_test.dart
//   } > /tmp/regen.dart && mv /tmp/regen.dart test/font/gfonts_all_test.dart

import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:pdf/widgets.dart';
import 'package:printing/printing.dart';

void main() {
  setUp(() {
    TestWidgetsFlutterBinding.ensureInitialized();
    // Every loader resolves through PdfBaseCache.defaultCache; a cache whose
    // resolve() always fails makes each loader take the deterministic
    // helvetica fallback path without any network access.
    PdfBaseCache.defaultCache = _FailingGfontsCache();
  });

  tearDown(() {
    PdfBaseCache.defaultCache = PdfMemoryCache();
  });

