/// A cache whose resolve() always throws, so each Google Fonts loader
/// exercises its fallback-to-helvetica path deterministically.
class _FailingGfontsCache extends PdfBaseCache {
  @override
  Future<void> add(String key, Uint8List bytes) async {}

  @override
  Future<Uint8List?> get(String key) async => null;

  @override
  Future<bool> contains(String key) async => false;

  @override
  Future<void> remove(String key) async {}

  @override
  Future<void> clear() async {}

  @override
  Future<Uint8List> resolve({
    required String name,
    required Uri uri,
    bool cache = true,
    Map<String, String>? headers,
  }) async {
    throw StateError('no network in tests: $name');
  }
}
